mapper.select:
select , m.name member_name
from reading_plan p
join member m on m.id = p.member_id

     and p.member_id = #{scopeMemberId}
     and p.member_id = #{q.memberId}

        and (m.name like concat('%', #{q.memberKeyword}, '%')
        or m.phone like concat('%', #{q.memberKeyword}, '%')
        or m.email like concat('%', #{q.memberKeyword}, '%'))

     and p.name like concat('%', #{q.planName}, '%')
     and p.status = #{q.status}
     and p.start_date >= #{q.startDateFrom}
     and p.start_date <= #{q.startDateTo}

order by p.updated_at desc

mapper.update:
update reading_plan
set version = version + 1, updated_at = now()
where id = #{id} and version = #{version}
